function setupReaders(){document.querySelectorAll('.doc-viewer').forEach(el=>{const pages=el.dataset.pagelist.split(',').map(Number);const holder=el.querySelector('.pages-here');function showOne(n){holder.innerHTML=makePaper(n,false);el.querySelectorAll('.page-pick').forEach(b=>b.classList.toggle('selected',Number(b.dataset.page)===n));el.querySelector('.show-all-pages').textContent='Exibir todas as páginas do módulo'}showOne(pages[0]);el.addEventListener('change',evt=>{if(evt.target.matches('.page-select'))showOne(Number(evt.target.value))});el.addEventListener('click',evt=>{let b=evt.target.closest('.page-pick');if(b){showOne(Number(b.dataset.page));b.scrollIntoView({behavior:'smooth',block:'nearest',inline:'nearest'})}let all=evt.target.closest('.show-all-pages');if(all){const opened=all.dataset.open==='yes';all.dataset.open=opened?'no':'yes';if(opened){showOne(pages[0]);all.textContent='Exibir todas as páginas do módulo'}else{holder.innerHTML=pages.map(n=>`<div class="doc-viewer" style="margin-bottom:18px">${makePaper(n)}</div>`).join('');all.textContent='Mostrar uma página por vez';el.querySelectorAll('.page-pick').forEach(b=>b.classList.remove('selected'))}}})})}
function setupArchive(){const parent=document.getElementById('archivePages');const search=document.getElementById('sourceSearch');const filter=document.getElementById('sourceFilter');const counter=document.getElementById('sourceCounter');parent.innerHTML=ALL.map(pg=>`<details class="archive-page" data-page="${pg.n}"><summary><span><span class="track-icon" style="width:36px;height:36px;border-radius:8px;font-size:.77rem">${pg.n}</span><span>Página ${pg.n}</span></span><span class="page-title">Procedimento original • transcrição textual completa</span></summary><div class="page-content">${makePaper(pg.n)}</div></details>`).join('');const docs=[...parent.querySelectorAll('.archive-page')];function apply(){let val=search.value.trim().toLowerCase();let group=filter.value;let set=PAGESETS[group]||ALL.map(p=>p.n);let count=0;for(let d of docs){let n=Number(d.dataset.page);let pg=ALL[n-1];let show=set.includes(n)&&(!val||pg.flat.includes(val)||pg.flat.normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(val.normalize('NFD').replace(/[\u0300-\u036f]/g,'')));d.hidden=!show;if(show)count++;if(!show)d.open=false}counter.textContent=`${count} página(s) encontradas de 76. A transcrição integral não foi abreviada.`,counter.setAttribute('aria-label',counter.textContent)}search.addEventListener('input',apply);filter.addEventListener('change',apply);apply()}
