let simState={idx:0,step:0,selected:null,completed:{}};
try{const v=JSON.parse(localStorage.getItem('u39-v3-scenarios')||'null');if(v&&typeof v==='object'){simState.completed=v.completed||{};if(Number.isInteger(v.idx)&&v.idx>=0&&v.idx<SCENARIOS.length)simState.idx=v.idx}}catch(e){}
function saveSim(){try{localStorage.setItem('u39-v3-scenarios',JSON.stringify({idx:simState.idx,completed:simState.completed}))}catch(e){}}
const SCENARIO_POSITION_MAP=(()=>{const a=Array.from({length:SCENARIOS.length*4},(_,i)=>i%3);let seed=20261019;for(let i=a.length-1;i>0;i--){seed=(1664525*seed+1013904223)>>>0;const j=seed%(i+1);[a[i],a[j]]=[a[j],a[i]];}return a})();
function scenarioOrder(ix,step){const correct=SCENARIOS[ix].steps[step].c,where=SCENARIO_POSITION_MAP[ix*4+step],rest=[0,1,2].filter(n=>n!==correct);if((ix+step)%2)rest.reverse();const order=new Array(3);order[where]=correct;let j=0;for(let i=0;i<3;i++)if(i!==where)order[i]=rest[j++];return order;}
function simMarkup(){const s=SCENARIOS[simState.idx],st=s.steps[simState.step],done=simState.selected!==null&&simState.selected===st.c,wrong=simState.selected!==null&&!done,order=scenarioOrder(simState.idx,simState.step);
 return `<div class="scenario-layout"><aside class="scenario-sidebar" aria-label="Cenários disponíveis">${SCENARIOS.map((x,i)=>`<button class="scenario-select ${i===simState.idx?'is-current':''}" data-scenario="${i}">${String(i+1).padStart(2,'0')} · ${esc(x.title)}${simState.completed[i]?' ✓':''}</button>`).join('')}</aside><article class="scenario-shell"><div class="scenario-card"><div class="block-heading"><h2>${esc(s.title)}</h2>${chip('technical')}</div><div class="question-number">DECISÃO ${simState.step+1} DE ${s.steps.length} · ${pageLink(s.ref)}</div><div class="stepmeter">${s.steps.map((_,i)=>`<span class="${i<=simState.step?'active':''}"></span>`).join('')}</div><div class="v3-sim-timeline"><span>Observar</span><span>Interpretar</span><span>Confrontar evidências</span><span>Justificar a decisão</span></div><h3>${esc(st.q)}</h3><div class="decision-options">${order.map((i,j)=>`<button type="button" data-answer="${i}" class="decision-option ${i===simState.selected?'selected':''} ${simState.selected!==null&&i===st.c?'v3-right':''} ${wrong&&i===simState.selected?'v3-wrong':''}" aria-pressed="${i===simState.selected}"><span class="option-letter">${'ABC'[j]}</span><span>${esc(st.opts[i])}</span></button>`).join('')}</div>${simState.selected!==null?`<div class="feedback ${done?'good':'bad'}" role="status"><strong>${done?'✓ Decisão fundamentada — avance':'✕ Consequência didática da decisão selecionada'}</strong><p>${wrong?'A alternativa escolhida não encontra respaldo no trecho de origem. Em uma situação real, interpretar uma indicação isolada como liberação pode omitir condições de proteção ou estabilização. Esta é uma consequência hipotética para estudo, não um comportamento simulado da planta.':''}</p><p>${esc(st.ex)}</p><p><strong>Evidência:</strong> ${pageLink(s.ref)} · ${chip('technical')}</p></div>`:''}<div class="scenario-bottom"><span class="muted-small">${simState.step+1}/${s.steps.length} decisões · escolhas embaralhadas · cenário fictício</span><div class="actions" style="margin-top:0"><button class="btn secondary" id="scenarioReset">Reiniciar cenário</button><button class="btn primary" id="scenarioNext" ${!done?'disabled':''}>${simState.step===s.steps.length-1?'Concluir cenário':'Próxima decisão →'}</button></div></div></div></article></div>`;
}
function drawSim(){const target=document.getElementById('simulator');target.innerHTML=simMarkup();target.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>{simState.idx=+b.dataset.scenario;simState.step=0;simState.selected=null;saveSim();drawSim()}));target.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{simState.selected=+b.dataset.answer;drawSim()}));target.querySelector('#scenarioReset').addEventListener('click',()=>{simState.step=0;simState.selected=null;drawSim()});target.querySelector('#scenarioNext').addEventListener('click',()=>{if(simState.selected!==SCENARIOS[simState.idx].steps[simState.step].c)return;if(simState.step<SCENARIOS[simState.idx].steps.length-1){simState.step++;simState.selected=null}else{simState.completed[simState.idx]=true;simState.idx=(simState.idx+1)%SCENARIOS.length;simState.step=0;simState.selected=null;saveSim();toast('Cenário concluído. Próximo cenário disponível.')}drawSim()})}

const QUESTIONS=[{"topic":"J-3901","level":"Intermediário","p":5,"q":"No condicionamento do V42, PI-39062A ainda indica pressão diferente de PI-39923. Qual leitura do item 3.6 corresponde à condição de equalização antes da abertura total da válvula de 16”?","o":["Abertura total depende da equalização dos dois PIs, com a válvula de 3” da mufla fechada.","Abertura total depende de PI-39062A superar PI-39923, mantendo a mufla aberta.","Abertura total depende da estabilização térmica em 370 °C, mesmo sem equalização.","Abertura total depende de PI-39923 cair abaixo do jusante, com a mufla parcialmente aberta."],"correct":0,"ex":"O item 3.6 condiciona a abertura completa da válvula de 16” à equalização PI-39062A/PI-39923, com a mufla de 3” toda fechada.","why":["Conjuga a igualdade de pressões e a condição da mufla.","Substitui equalização por sobrepressão do jusante.","Confunde condição hidráulica prévia com a etapa térmica seguinte.","Prevê diferencial de pressão e mufla aberta, sem respaldo no texto."],"focus":"Compare a relação entre os dois PIs e a posição requerida para a mufla."},{"topic":"J-3901","level":"Intermediário","p":5,"q":"TI-39124A atingiu 370 °C após aquecimento do V42. Qual afirmação sobre a rampa está estritamente sustentada no procedimento?","o":["É a temperatura mínima do V42 após rampa de 60 °C/h; a temperatura do rotor não foi informada.","É a temperatura do metal da turbina após rampa de 60 °C/h; o vapor não foi especificado. pelo TI-39124A.","É a temperatura mínima do V42 após rampa de 50 °C/h; a leitura de metal não foi fornecida.","É o limite do vapor V42 após rampa de 100 °C/h; o metal acompanha o mesmo gradiente."],"correct":0,"ex":"O item 3.7 especifica 60 °C/h no V42 até 370 °C, no mínimo; não fornece curva térmica do metal.","why":["Distingue a temperatura do vapor dos valores do metal.","Atribui indevidamente a medição ao rotor.","Transfere ao V42 a taxa associada ao riser.","Transfere a taxa da fase densa e presume comportamento do metal."],"focus":"Identifique qual fluido é monitorado por TI-39124A, sem inferir temperatura do metal."},{"topic":"J-3901","level":"Avançado CIC","p":5,"q":"Depois do condicionamento térmico e com a equipe preparando a máquina, qual sequência de reset aparece no item 3.8, sem supor permissivos adicionais?","o":["Reset local seguido de reset no SDCD; as duas ações são descritas como simultâneas.","Reset no SDCD seguido de reset local; demais permissivos exigem documentação própria.","Reset no SDCD seguido de SAFE RUN; o reset local é dispensado pelo checklist.","Reset local seguido de AIR SERVICE; o reset pelo SDCD é previsto somente depois."],"correct":1,"ex":"O item 3.8 registra reset no SDCD e logo em seguida reset no painel local. Isso não constitui toda a sequência individual de partida.","why":["Inverte a ordem e introduz simultaneidade não indicada.","Preserva a ordem e limita a inferência documental.","Troca a segunda ação por um modo de operação posterior.","Antecipação de AIR SERVICE que não substitui os resets."],"focus":"Observe a ordem explícita dos comandos e não complete lacunas com suposições."},{"topic":"J-3901","level":"Avançado CIC","p":19,"q":"O J-3901 permaneceu aproximadamente 20 min a 1.400 RPM e iniciou aceleração automática. Que conclusão é válida sobre o próximo ponto do checklist?","o":["Chegada a 3.356 RPM implica AIR SERVICE; SAFE RUN é utilizado antes dos 1.400 RPM.","Chegada a 3.356 RPM implica SAFE RUN; a taxa da aceleração continua não informada.","Chegada a 3.356 RPM implica SAFE RUN; a rampa entre patamares dura 20 min exatos.","Chegada a 3.356 RPM implica AIR SERVICE; a passagem para SAFE RUN depende do J-3902."],"correct":1,"ex":"O item 14 prevê cerca de 20 min a 1.400 RPM, subida automática até 3.356 RPM e colocação em SAFE RUN nesse ponto; a taxa RPM/min não é fornecida.","why":["Antecipação de AIR SERVICE e deslocamento de SAFE RUN.","Correlaciona corretamente velocidade e modo, sem inventar a taxa.","Confunde o tempo de permanência com o tempo de aceleração.","Cria dependência do J-3902 ausente do trecho."],"focus":"Separe tempo de permanência, taxa de aceleração e transição de modo."},{"topic":"J-3901","level":"Avançado CIC","p":19,"q":"Na preparação da mudança para AIR SERVICE, qual interpretação da orientação sobre FV-39004 e HV-39003 é mais fiel ao item 14?","o":["Conferir a ação sobre as duas válvulas antes da transição, considerando o diferencial de pressão.","Conferir somente a HV-39003 depois da transição, considerando a rotação estabilizada. ao longo da rampa.","Conferir somente a FV-39004 após a transição, considerando a pressão já equalizada.","Conferir ambas após a transição, pois o diferencial de pressão é tratado em SAFE RUN."],"correct":0,"ex":"O checklist registra “descolar” FV-39004 pelo FIC-39004 e HV-39003 pelo HIC-39003 antes de AIR SERVICE para evitar travamento por ΔP.","why":["Conserva as duas válvulas, o momento e a finalidade.","Deixa de fora a FV-39004 e desloca a verificação.","Deixa de fora a HV-39003 e presume equalização.","Desloca ambas para depois da transição, contra o texto."],"focus":"Compare o momento da ação, as duas malhas e a finalidade de evitar ΔP."},{"topic":"J-3901","level":"Intermediário","p":19,"q":"O documento relaciona 3.356 RPM a 0% de sinal de saída do controlador de performance. Qual cuidado evita uma inferência indevida?","o":["Tratar 0% como posição física da HV-39003 durante a aceleração do J-3901.","Tratar 0% como vazão de ar medida na descarga do compressor J-3901.","Tratar 0% como referência daquele controlador, não como velocidade nula do rotor.","Tratar 0% como confirmação de que AIR SERVICE já está liberado ao J-3901."],"correct":2,"ex":"O item 14 usa 0% especificamente para o sinal de saída do controlador de performance na rotação de 3.356 RPM.","why":["Confunde o sinal de performance com a posição da HV-39003.","Confunde o sinal de performance com a leitura de vazão na descarga.","Associa corretamente o percentual ao sinal do controlador de performance.","Converte a referência do controlador em permissão para um modo operacional."],"focus":"Identifique a variável à qual o percentual foi associado."},{"topic":"J-3901","level":"Avançado CIC","p":18,"q":"No item 13, antes do J-3901 entrar em operação, qual conjunto pertence à preparação do sistema de ar e torch-oil?","o":["FV-39844 para flauta; FV-39030/39031 alinhadas; reset da FV-39031 conforme checklist.","FV-39844 para flauta; FV-39030/39031 fechadas; reset da FV-39031 após carga. com confirmação no campo.","FV-39844 para flauta; FV-39030/39031 alinhadas; reset da FV-39031 após carga.","FV-39844 isolada; FV-39030/39031 alinhadas; reset da FV-39031 antes da máquina."],"correct":0,"ex":"Os itens 13.2, 13.4 e 13.5 registram alinhamento de FV-39844 e FV-39030/FV-39031, além do reset da FV-39031.","why":["Agrupa os estados e resets previstos na preparação.","Troca alinhamento por fechamento e posterga reset.","Mantém alinhamentos, mas posterga indevidamente o reset.","Inverte a condição da FV-39844, apesar de manter as demais."],"focus":"Cruze os itens 13.2, 13.4 e 13.5, mantendo a ordem documental."},{"topic":"J-3901","level":"Avançado CIC","p":19,"q":"Um trainee afirma que a passagem por 3.356 RPM confirma que o J-3901 atravessou todas as velocidades críticas. Como avaliar essa afirmação?","o":["É comprovada pelo patamar de SAFE RUN e pela indicação de 0% do controlador.","É comprovada pela permanência anterior de aproximadamente 20 min a 1.400 RPM.","Não é comprovada: o checklist traz os patamares, mas não as faixas críticas.","Não é comprovada: o checklist traz as faixas críticas, mas omite os patamares."],"correct":2,"ex":"O item 14 remete à partida conforme procedimento específico. Não enumera velocidades críticas ou seus critérios de passagem.","why":["Sinal de performance não documenta faixas críticas.","Duração de patamar não documenta velocidades críticas.","Reconhece os limites da evidência disponível.","Afirma existir no checklist informação que não está presente."],"focus":"Diferencie patamares explicitados de dados que dependem do fabricante."},{"topic":"J-3902","level":"Avançado CIC","p":37,"q":"A TFD está na faixa prevista e os ciclones estão aquecidos. Para preparar a aceleração do J-3902, que conjunto ainda precisa ser considerado no item 33?","o":["Retificador em 70% AUT, regenerador ≥ 42% e vaso separador em torno de 1,1 kgf/cm².","Retificador em 70% MAN, regenerador ≥ 42% e vaso separador em torno de 1,1 kgf/cm².","Retificador em 70% AUT, regenerador ≥ 27% e vaso separador em torno de 1,1 kgf/cm².","Retificador em 70% AUT, regenerador ≥ 42% e vaso separador em torno de 1,5 kgf/cm²."],"correct":0,"ex":"Os itens 33.1, 33.2 e 33.4 registram LIC-39001 em AUT a 70%, nível do regenerador mínimo 42% e PI-39015 em torno de 1,1 kgf/cm².","why":["Reúne corretamente três condições da mesma etapa.","Altera AUT para MAN no retificador.","Substitui o mínimo de partida do regenerador por outro valor citado no PDF.","Usa referência de pressão do vaso de outra etapa de partida."],"focus":"Todos os números são referências possíveis no documento; associe-os à etapa 33."},{"topic":"J-3902","level":"Avançado CIC","p":36,"q":"A fase densa chegou a 660 °C, mas uma das pernas de ciclone ainda está a 485 °C. Como interpretar o marco térmico do item 32 para elevar o J-3902?","o":["A média da fase densa é suficiente; as pernas entram como referência apenas na carga.","A rotação pode ser elevada se TIC-39001 não ultrapassar 560 °C, mesmo com ciclone a 485 °C.","O critério térmico está incompleto; o item 32 inclui pernas de ciclones com mínimo de 500 °C.","O critério térmico está completo se a pressão diferencial PDIC-39029 estiver em 0,2 kgf/cm²."],"correct":2,"ex":"O item 32 inclui TFD entre 650 e 680 °C e temperaturas das pernas TI-39018A...D de pelo menos 500 °C; uma leitura de 485 °C não atende ao conjunto.","why":["Desconsidera um requisito térmico expresso.","Substitui condição dos ciclones por TRX isolada.","Confronta valor observado com o mínimo do item 32.","Troca condição térmica por condição de pressão diferencial."],"focus":"Avalie simultaneamente as temperaturas da fase densa e das pernas dos ciclones."},{"topic":"J-3902","level":"Avançado CIC","p":38,"q":"Para elevar a rotação, o item 33 prepara o balanço do conversor. Qual sequência de válvulas de catalisador e suporte de gás é registrada?","o":["Fechar L-3901 antes de L-3902 e restringir gás-in para estabilizar a sucção.","Fechar L-3902 pelo TIC-39001, aguardar L-3901 fechar e reforçar gás-in.","Manter L-3902 aberta pelo TIC-39001, aguardar L-3901 e reduzir gás-in.","Manter L-3901 aberta em automático, fechar L-3902 e restringir gás-in."],"correct":1,"ex":"Os itens 33.7–33.9 dispõem fechamento de L-3902, confirmação de L-3901 fechada e reforço de alinhamento de gás-in.","why":["Altera a sequência e restringe gás-in.","Preserva a sequência e os suportes de pressão.","Altera L-3902 para aberta e reduz gás-in.","Não exige fechamento de L-3901 nem reforço de gás-in."],"focus":"Associe os três itens 33.7, 33.8 e 33.9 na ordem em que aparecem."},{"topic":"J-3902","level":"Intermediário","p":38,"q":"No início da aceleração, o J-3902 está em 1.200 RPM. Qual é a condição da FV-39182 e do sinal do antissurge explicitada no item 34.3?","o":["FV-39182 aberta e controlador a 100%, condição prevista para o patamar de 1.200 RPM.","FV-39182 fechada e controlador a 0%, condição prevista para o patamar de 1.200 RPM.","FV-39182 aberta e controlador a 0%, condição prevista para o patamar de 1.200 RPM.","FV-39182 fechada e controlador a 100%, condição prevista para o patamar de 1.200 RPM."],"correct":1,"ex":"O item 34.3 registra FV-39182 fechada com sinal de saída do controlador antissurge em 0% a 1.200 RPM.","why":["Troca simultaneamente o estado e o sinal.","Associa corretamente posição, sinal e rotação.","Troca apenas o estado da válvula.","Troca apenas o sinal de saída do controlador."],"focus":"Repare na diferença entre a condição a 1.200 RPM e a verificação a 1.300 RPM."},{"topic":"J-3902","level":"Avançado CIC","p":39,"q":"Na passagem por 1.300 RPM, FIC-39182 chega a 100%, porém o campo informa 70% de abertura da FV-39182. Qual comparação define a interpretação?","o":["O comando chegou a 100%, mas a posição real não atende aos 100% previstos para a FV-39182.","A posição real chegou a 70%, valor aceito pelo checklist quando o sinal está em 100%.","O comando chegou a 100%, logo a confirmação de posição no campo torna-se dispensável.","A posição real chegou a 70%, valor válido porque 1.300 RPM é velocidade de permanência."],"correct":0,"ex":"A página 39 exige FIC-39182 com sinal 100% e confirmação pelo campo de FV-39182 aberta 100%; comando não substitui posição.","why":["Distingue corretamente comando e abertura efetiva.","Inventa tolerância de 70% não publicada.","Dispensa a confirmação expressa no procedimento.","Trata 1.300 RPM como permanência, sem base documental."],"focus":"A confirmação precisa contemplar simultaneamente comando e posição efetiva."},{"topic":"J-3902","level":"Avançado CIC","p":39,"q":"Ainda na passagem de 1.300 RPM, o FIC-39182 indica 100% e a FV-39182 não abre. Qual previsão de proteção está efetivamente escrita?","o":["Conservar a aceleração até 5.000 RPM e confirmar nova indicação em regime.","Manter 1.300 RPM como patamar até a estabilização do PI-39015.","Tripar imediatamente o J-3902 pela HS39490, segundo o item 34.","Transferir para REMOTO pela HS-393054 antes de verificar a FV-39182."],"correct":2,"ex":"A página 39 estabelece trip imediato pelo HS39490 quando a FV-39182 não abre nessa verificação.","why":["Adia a ação para uma velocidade posterior.","Cria um patamar que o documento não define.","Reproduz a condição documentada para falta de abertura.","Troca ação de proteção por transferência de modo posterior."],"focus":"A pergunta trata de ausência de abertura, não apenas de divergência pequena."},{"topic":"J-3902","level":"Avançado CIC","p":39,"q":"O PI-39015 apresenta queda brusca durante a aceleração. Que evidência adicional delimita o evento descrito no item 34.6?","o":["A confirmação do valor de saída do FIC-39182 sem observar o retificador.","A evidência de arraste de catalisador do retificador pelo LIC-39001.","A redução do PDIC-39029, independentemente da tendência do retificador.","A variação de velocidade pelo SI-393056A, independentemente do retificador."],"correct":1,"ex":"O texto relaciona queda brusca do PI-39015 seguida de arraste de catalisador do retificador, monitorado pelo LIC-39001.","why":["Acrescenta outro sinal, mas omite o elemento associado ao evento descrito.","Combina as duas observações presentes na descrição do item 34.6.","Supõe que diferencial sozinho comprove arraste de catalisador.","Supõe que rotação sozinha comprove arraste de catalisador."],"focus":"Distinga “queda de pressão” do conjunto de evidências do evento descrito."},{"topic":"J-3902","level":"Intermediário","p":39,"q":"O TO aciona HS-39053 IDLE/RATED. Em auditoria, pedem taxa de aceleração em RPM/min. Qual conclusão decorre da documentação disponível?","o":["A razão é dedutível entre 1.200 e 1.300 RPM, com tempo de passagem definido no item 34.","A razão é dedutível do intervalo de 15 min entre drenagens e da diferença até 5.000 RPM.","A razão é definida no PEAK505, mas a taxa numérica não foi publicada neste checklist.","A razão é dedutível do tempo de estabilização do PI-39015 na fase de aceleração."],"correct":2,"ex":"A página 39 registra a aceleração automática configurada no PEAK505, mas não informa duração nem parâmetro de RPM/min.","why":["O PDF não apresenta tempo entre os dois pontos de rotação.","A periodicidade da drenagem não é o tempo da aceleração.","O governador é citado, mas o ajuste de RPM/min não é informado.","Estabilização de pressão não fornece a programação de aceleração."],"focus":"Sem tempo ou taxa programada, os patamares de RPM não bastam para cálculo."},{"topic":"J-3902","level":"Avançado CIC","p":39,"q":"A indicação SI-393056A chegou a 5.000 RPM, mas a pressão e a vibração seguem variando. Como ler a condição de estabilização prevista?","o":["A velocidade nominal basta, pois as vibrações são verificadas somente após REMOTO. nas condições registradas.","O patamar de rotação foi alcançado, mas falta confirmar estabilização mecânica e de pressão.","A transferência para REMOTO comprova estabilização, independentemente de PI-39015.","A pressão do vaso só é relevante durante 1.200 RPM e deixa de ser monitorada a 5.000."],"correct":1,"ex":"O item 34 requer acompanhar vibrações/deslocamento axial, aguardar 5.000 RPM e estabilização da máquina e do balanço de pressão.","why":["Exclui critérios mecânicos citados no acompanhamento.","Integra rotação, estabilidade mecânica e de pressão.","Transforma mudança de modo em certificação automática.","Desconsidera monitoramento do vaso durante a aceleração."],"focus":"Compare o evento “atingir rotação” com a condição “estabilizar conjunto e processo”."},{"topic":"J-3902","level":"Avançado CIC","p":41,"q":"Após 5.000 RPM, o checklist retoma circulação de catalisador. Qual associação de controles pertence à etapa 35?","o":["PI-39015 perto de 1,1 kgf/cm² e PDIC-39029 perto de 0,2 kgf/cm².","PI-39015 perto de 1,2 kgf/cm² e PDIC-39029 perto de 0,1 kgf/cm².","PI-39015 perto de 1,1 kgf/cm² e PDIC-39029 perto de 0,4 kgf/cm².","PI-39015 perto de 1,5 kgf/cm² e PDIC-39029 perto de 0,2 kgf/cm²."],"correct":0,"ex":"O item 35.4 mantém PI-39015 em 1,1 kgf/cm² e o item 35.5 define ΔP regenerador/vaso de 0,2 kgf/cm².","why":["Mantém os dois valores referentes à mesma fase.","Altera ambas as referências.","Altera apenas a referência do diferencial.","Emprega pressão do vaso de outra fase da partida."],"focus":"Não confunda pressão do vaso com diferencial entre vaso e regenerador."},{"topic":"J-3902","level":"Avançado CIC","p":40,"q":"No texto da página 40 aparece PIC29211, enquanto outras etapas citam PIC-39211. Qual tratamento protege a rastreabilidade da instrução?","o":["Unificar os dois tags sem registro, pois o equipamento já está a 5.000 RPM.","Usar PIC29211 como malha diferente e transferir o controle sem conferência.","Preservar a divergência escrita e confrontar com diagrama e lista de instrumentos vigentes.","Corrigir todos os tags para PIC29211 e tratar a diferença como revisão de lógica."],"correct":2,"ex":"A fonte apresenta PIC29211 na página 40 e PIC-39211 em outras etapas; não contém uma errata validada.","why":["Corrige sem evidência a identificação documental.","Supõe duas malhas diferentes sem validação.","Reconhece divergência e exige comprovação documental externa.","Transforma erro possível em revisão de instrumento."],"focus":"Essa é uma questão de qualidade documental: não corrigir silenciosamente tags."},{"topic":"J-3902","level":"Avançado CIC","p":38,"q":"A equipe prepara o J-3902 para a elevação. Que combinação de verificações da carcaça e do sistema de proteção está no item 34?","o":["Drenar os cinco pontos em conjunto e confirmar a abertura da FV-39182 apenas a 5.000 RPM. após a aceleração.","Drenar os cinco pontos um por vez e manter operador junto à FV-39182 para confirmar abertura.","Drenar os cinco pontos um por vez e manter FV-39182 isolada durante toda a aceleração.","Drenar os cinco pontos em conjunto e dispensar campo caso o FIC-39182 indique 100%."],"correct":1,"ex":"O item 34.1 mantém TO em campo para confirmar a FV-39182; o item 34.4 pede drenagem dos cinco pontos, um por vez.","why":["Altera forma de drenagem e posterga confirmação.","Associa duas verificações complementares e documentadas.","Prevê isolamento da válvula durante a aceleração.","Altera drenagem e confunde comando com posição."],"focus":"Combine a exigência de presença do TO com a drenagem da carcaça."},{"topic":"Conversor","level":"Intermediário","p":21,"q":"A média TIC-39031 indica 385 °C e os TI da fase densa estão a partir de 352 °C. Qual par de critérios corresponde ao item 17 para torch-oil?","o":["TIs individuais no mínimo 350 °C e média TIC-39031 no mínimo 380 °C.","TIs individuais no mínimo 380 °C e média TIC-39031 no mínimo 350 °C.","TIs individuais no mínimo 350 °C e média TIC-39031 no mínimo 500 °C.","TIs individuais no mínimo 500 °C e média TIC-39031 no mínimo 380 °C."],"correct":0,"ex":"O item 17 distingue mínimo de 350 °C para os TI-39031A...L e média de pelo menos 380 °C no TIC-39031.","why":["Conserva os limites diferenciados por leitura.","Inverte média e sensores individuais.","Confunde referência de cat-coolers com torch-oil.","Importa mínimo de ciclones para TI da fase densa."],"focus":"Verifique se os limites são de cada termopar ou da média."},{"topic":"Conversor","level":"Avançado CIC","p":22,"q":"A TFD sobe, mas a equipe observa dispersão entre TI-39031A...L. Qual interpretação é mais consistente com os itens 18 e 24?","o":["A média controla a rampa; o afastamento entre TIs deve ser examinado e pode exigir ARO específica.","A média controla a rampa; o afastamento entre TIs fica sem relevância até início da carga. durante o aquecimento.","A média controla a rampa; o afastamento entre TIs exige usar 50 °C/h como nova taxa geral.","A média controla a rampa; o afastamento entre TIs autoriza usar 370 °C como novo limite."],"correct":0,"ex":"O item 18 registra rampa de 100 °C/h até 680 °C e o item 24.1 exige observar os termopares e tratar desvios via ARO específica.","why":["Preserva critério de média e atenção às diferenças entre sensores.","Retira verificação explícita da fase densa.","Transfere a taxa do riser para a fase densa.","Transfere temperatura do V42 para o regenerador."],"focus":"Os parâmetros de média não substituem a avaliação dos termopares individuais."},{"topic":"Conversor","level":"Avançado CIC","p":32,"q":"Durante circulação inicial, TI-39004/39007/39009/39011 indicam aquecimento rápido do riser. Qual estratégia é registrada no item 26?","o":["Manipular L-3902 via TIC-39001 em MAN buscando cerca de 50 °C/h no riser.","Manipular L-3902 via TIC-39001 em AUT buscando cerca de 100 °C/h no riser.","Manipular L-3901 via LIC-39001 em MAN buscando cerca de 60 °C/h no riser.","Manipular L-3901 via LIC-39001 em AUT buscando cerca de 100 °C/h no riser."],"correct":0,"ex":"O item 26.1 acompanha os quatro TIs e prevê abertura lenta da L-3902 via TIC-39001 MAN, buscando cerca de 50 °C/h.","why":["Relaciona válvula, malha, modo e rampa corretos.","Troca modo e taxa pela rampa do regenerador.","Troca válvula/malha e a taxa pelo V42.","Troca válvula/malha e adota a taxa do regenerador."],"focus":"As alternativas só mudam malha, modo e taxa: confronte todos os três."},{"topic":"Conversor","level":"Avançado CIC","p":22,"q":"A fase densa atingiu 680 °C e a equipe avalia introduzir carga. Uma perna de ciclone ainda indica 465 °C. O que o checklist permite concluir?","o":["A TFD a 680 °C é condição suficiente, desde que a TRX também esteja em 560 °C. ainda que com TRX estável.","A temperatura de 465 °C está abaixo de 470 °C; o critério térmico de ciclones não foi atendido.","A temperatura de 465 °C supera 350 °C; o critério térmico dos ciclones já foi atendido.","A TFD a 680 °C supera 500 °C; a leitura individual da perna não limita a etapa."],"correct":1,"ex":"O item 18 adverte não injetar carga antes de as pernas dos ciclones atingirem 470 °C, idealmente 500 °C.","why":["Confunde média da fase densa com aquecimento local dos ciclones.","Confronta a leitura da perna com o mínimo citado.","Utiliza limite de torch-oil para liberação de carga.","Substitui leitura de perna por média de fase densa."],"focus":"Compare a leitura individual com o mínimo e o valor ideal das pernas."},{"topic":"Conversor","level":"Intermediário","p":25,"q":"O TIC-39031 chega a 500 °C durante a preparação do regenerador. Qual transição da unidade é situada nesse marco no item 22?","o":["Preparar os cat-coolers para operação conforme a sequência individual de condicionamento.","Completar imediatamente o carregamento de carga no riser pelo ramal superior. sem avaliar TRX.","Elevar imediatamente o J-3902 de 1.200 a 5.000 RPM pelo controle PEAK505.","Normalizar imediatamente o bypass de todos os intertravamentos do conversor."],"correct":0,"ex":"O item 22 associa média de 500 °C da fase densa ao início do processo de colocação dos cat-coolers em operação.","why":["Identifica a etapa térmica do item 22 sem transferir liberações.","Antecipação de carga não estabelecida nesse marco.","Aceleração do J-3902 é etapa posterior com outros critérios.","Bypasses são normalizados individualmente por critérios próprios."],"focus":"Marcos térmicos não liberam automaticamente máquinas nem bypasses."},{"topic":"Conversor","level":"Avançado CIC","p":7,"q":"Ao avaliar o reset do TSLL39010B (baixa TRX) na condição de bypass de partida, que estrutura lógica o item 7 registra?","o":["Carga acima de 1.637 m³/d em um dos ramais OU TRX acima de 525 °C.","Carga acima de 1.637 m³/d em ambos os ramais E TRX acima de 525 °C.","Carga acima de 1.259 m³/d em um dos ramais E TRX acima de 500 °C.","Carga acima de 1.259 m³/d em ambos os ramais OU TRX acima de 500 °C."],"correct":0,"ex":"O PDF descreve alternativas ligadas por “ou”: ramal inferior > 1.637 m³/d, ramal superior > 1.637 m³/d ou TRX > 525 °C.","why":["Preserva operadores lógicos e limites do reset.","Exige conjunção inexistente entre ramais e TRX.","Utiliza limites da condição de trip em vez de reset.","Mistura limites de trip e conectivo, sem respaldo."],"focus":"Compare as palavras “ou” e “e” e não misture limites de trip com reset."},{"topic":"Conversor","level":"Avançado CIC","p":7,"q":"Sem acendimento do B-3901, qual conjunto o documento associa ao reset do FSLL39003B de baixa vazão de ar?","o":["Fase densa > 400 °C e vazão de ar > 3.500 m³/d.","Fase densa > 400 °C ou vazão de ar > 3.500 m³/d.","Fase densa > 350 °C e vazão de ar > 3.500 m³/d.","Fase densa > 400 °C e vazão de ar > 1.350 m³/d."],"correct":0,"ex":"Na situação 02, sem necessidade de acender o forninho, o item 7 exige TFD > 400 °C e ar > 3.500 m³/d.","why":["Conserva ambas as condições cumulativas do caso sem forninho.","Troca a relação AND por OR.","Insere temperatura de outra fase.","Insere valor de atuação de baixa vazão no lugar do reset."],"focus":"Diferencie a condição “sem forninho” da “com forninho” e respeite o conectivo."},{"topic":"Conversor","level":"Avançado CIC","p":7,"q":"Na revisão do FSLL39044B, o PDF mostra atuação abaixo de 550 t/d por 300 s e reset acima de 50 t/d por 30 s. Qual registro técnico é correto?","o":["Registrar os valores exatamente como impressos e solicitar confrontação com a matriz vigente.","Trocar os valores de atuação e reset no Concept até o intertravamento ficar simétrico. no painel.","Eliminar os tempos de 300 s e 30 s para manter apenas os limiares em t/d.","Aplicar diretamente o limite de 50 t/d como novo ponto de atuação da função."],"correct":0,"ex":"As páginas 7–8 trazem tais números; a discrepância exige conferência na documentação controlada, sem correção silenciosa.","why":["Preserva rastreabilidade e explicita pendência de validação.","Altera sem confirmação os parâmetros do instrumento.","Descarta atrasos de atuação/reset que constam na fonte.","Promove parâmetro de reset a trip sem base documental."],"focus":"Não se deve ajustar parâmetros apenas por parecerem mais coerentes."},{"topic":"Conversor","level":"Avançado CIC","p":41,"q":"Com o J-3902 estabilizado a 5.000 RPM, inicia-se nova circulação. Qual associação entre instrumento e rampa é explicitada na etapa 35?","o":["L-3902 pelo TIC-39001 em MAN; acompanhar 50 °C/h no riser pelos quatro TIs.","L-3902 pelo TIC-39001 em AUT; acompanhar 100 °C/h no riser pelos quatro TIs.","L-3901 pelo LIC-39001 em MAN; acompanhar 50 °C/h na fase densa pelos TIs.","L-3901 pelo LIC-39001 em AUT; acompanhar 60 °C/h na fase densa pelos TIs."],"correct":0,"ex":"O item 35.7 repete o uso de L-3902 via TIC-39001 em MAN para rampa do riser de 50 °C/h (TI-39004, 39007, 39009 e 39011).","why":["Associa válvula, malha, modo e variável monitorada.","Transfere taxa do regenerador e modo AUT.","Desloca para L-3901 e leitura da fase densa.","Transfere taxa do V42 e desloca a malha de atuação."],"focus":"Este é o mesmo princípio térmico reaplicado após a aceleração do J-3902."},{"topic":"Conversor","level":"Avançado CIC","p":45,"q":"Na primeira introdução de carga no riser, qual critério vincula a rampa de carga à prevenção de queda rápida da TRX?","o":["Carga introduzida lentamente e vapor de dispersão acima de 4%p em relação à carga.","Carga introduzida rapidamente e vapor de dispersão acima de 4%p em relação à carga.","Carga introduzida lentamente e vapor de dispersão abaixo de 4%p em relação à carga.","Carga introduzida rapidamente e vapor de dispersão abaixo de 4%p em relação à carga."],"correct":0,"ex":"O item 41 associa introdução lenta da carga à prevenção da queda brusca da TRX e vapor de dispersão acima de 4%p na rampa.","why":["Preserva tanto a velocidade de introdução como a relação de dispersão.","Altera a introdução para rápida, contrariando o texto.","Altera a relação de dispersão para abaixo de 4%p.","Inverte os dois requisitos documentados."],"focus":"Observe simultaneamente a velocidade de introdução de carga e o vapor de dispersão."}];

